INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Fremdschlüssel dasselbe wie ein Primärschlüssel?', 2, '[{"text": "Nein", "correct": true, "because": "Verweis vs. eindeutige ID"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Fremdschlüssel?', 3, '[{"text": "Beziehungen zwischen Tabellen herstellen", "correct": true, "because": "Datenverknüpfung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Daten löschen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Fremdschlüssel?', 5, '[{"text": "Verweist auf Primärschlüssel", "correct": true, "because": "Referenz"}, {"text": "Kann NULL sein", "correct": true, "because": "Optional"}, {"text": "Muss eindeutig sein", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fremdschlüssel verknüpft Tabellen. b) Er ist immer eindeutig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht eindeutig nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Fremdschlüssel?', 4, '[{"text": "Referenzielle Integrität", "correct": false, "because": "Kernprinzip"}, {"text": "Zieltabelle", "correct": false, "because": "Verknüpfung"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Fremdschlüssel NULL-Werte erlaubt?', 2, '[{"text": "Ja", "correct": true, "because": "Optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Fremdschlüssel in SQL?', 3, '[{"text": "FOREIGN KEY Constraint", "correct": true, "because": "Referenz definieren"}, {"text": "PRIMARY KEY Constraint", "correct": false, "because": "Andere Funktion"}, {"text": "UNIQUE Constraint", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Fremdschlüssel?', 5, '[{"text": "Datenkonsistenz", "correct": true, "because": "Integrität"}, {"text": "Beziehungen klar definieren", "correct": true, "because": "Verknüpfung"}, {"text": "Schnellere Datenverarbeitung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fremdschlüssel verhindern inkonsistente Daten. b) Sie müssen immer eindeutig sein. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eindeutigkeit optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Fremdschlüssel?', 4, '[{"text": "Zieltabelle", "correct": false, "because": "Referenz nötig"}, {"text": "Primärschlüssel", "correct": false, "because": "Verweisziel"}, {"text": "Physisches Handbuch", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Fremdschlüssel auf einen Primärschlüssel verweisen?', 2, '[{"text": "Ja", "correct": true, "because": "Standardregel"}, {"text": "Nein", "correct": false, "because": "Typischerweise ja"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Befehle nutzen Fremdschlüssel?', 4, '[{"text": "CREATE TABLE", "correct": true, "because": "Definition"}, {"text": "ALTER TABLE", "correct": true, "because": "Hinzufügen"}, {"text": "PRINT", "correct": false, "because": "Kein SQL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fremdschlüssel die Leistung verschlechtern. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Integritätsprüfung"}, {"text": "Nein", "correct": false, "because": "Kann Leistung beeinflussen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Fremdschlüssel?', 3, '[{"text": "Referenzielle Integrität", "correct": true, "because": "Datenkonsistenz"}, {"text": "Papierdokumente", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Integrität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fremdschlüssel können NULL sein. b) Sie sind immer Primärschlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht Primärschlüssel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkungen hat ein Fremdschlüssel?', 5, '[{"text": "Referenz muss existieren", "correct": true, "because": "Integrität"}, {"text": "Kann nicht gelöscht werden", "correct": true, "because": "Abhängigkeit"}, {"text": "Muss immer eindeutig sein", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Fremdschlüssel unwichtig?', 3, '[{"text": "Referenz", "correct": false, "because": "Grundlage"}, {"text": "Integrität", "correct": false, "because": "Kernmerkmal"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Fremdschlüssel auf eine andere Spalte verweisen?', 3, '[{"text": "Ja", "correct": true, "because": "Wenn eindeutig"}, {"text": "Nein", "correct": false, "because": "Flexibel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Fremdschlüssel mehrere Tabellen verbinden kann?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Referenz"}, {"text": "Ja", "correct": false, "because": "Ein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für einen Fremdschlüssel zentral?', 4, '[{"text": "Referenz auf Primärschlüssel", "correct": true, "because": "Kernprinzip"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Kein Fokus"}]');
